/**
 * generate-codex-protocol.mjs -- the pinned Codex app-server's protocol types, generated into `src/codex-protocol/` with the import paths Node ESM loads.
 *
 * Codex writes its own TypeScript bindings (`codex app-server generate-ts`,
 * from its Rust types through ts-rs). They are committed rather than
 * generated at build time, so a check never needs Codex, and regenerated by
 * this script whenever the pin moves:
 * `pnpm --filter @luke/agent-runner generate:codex-protocol`. The one change
 * made to Codex's output is each relative import's `.js` suffix, which the
 * repository's checks require of every package.
 */

import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

/** The Codex the runner drives in the sandbox (P16's pin; P17 puts it in the image). */
const CODEX_PACKAGE = "@openai/codex@0.163.0";

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const target = path.join(packageRoot, "src", "codex-protocol");

/** Every `.ts` file under a directory, recursively. */
function typeScriptFiles(directory) {
  return readdirSync(directory, { withFileTypes: true, recursive: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith(".ts"))
    .map((entry) => path.join(entry.parentPath, entry.name));
}

const scratch = mkdtempSync(path.join(tmpdir(), "codex-protocol-"));
try {
  execFileSync("npx", ["--yes", CODEX_PACKAGE, "app-server", "generate-ts", "--out", scratch], {
    stdio: "inherit",
  });
  for (const file of typeScriptFiles(scratch)) {
    const text = readFileSync(file, "utf8").replace(/from "(\.\.?\/[^"]*)"/gu, (_, specifier) => {
      const resolved = path.resolve(path.dirname(file), specifier);
      const isDirectory = existsSync(resolved) && statSync(resolved).isDirectory();
      return `from "${specifier}${isDirectory ? "/index" : ""}.js"`;
    });
    writeFileSync(file, text);
  }
  rmSync(target, { recursive: true, force: true });
  execFileSync("cp", ["-R", scratch, target]);
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
